import{_ as s,o as a,c as t,ax as i}from"./chunks/framework.Bnt0oLax.js";const g=JSON.parse('{"title":"Manage Scripts and Stylesheets","description":"Register sitewide scripts and stylesheets from the CLI, either as local files or as external hosted URLs, and scope them to specific pages.","frontmatter":{"description":"Register sitewide scripts and stylesheets from the CLI, either as local files or as external hosted URLs, and scope them to specific pages."},"headers":[],"relativePath":"cli/manage-scripts-and-styles.md","filePath":"cli/manage-scripts-and-styles.md"}'),n={name:"cli/manage-scripts-and-styles.md"};function d(r,e,l,o,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/manage-scripts-and-styles.md for this page in Markdown format</div><h1 id="manage-scripts-and-stylesheets" tabindex="-1">Manage Scripts and Stylesheets <a class="header-anchor" href="#manage-scripts-and-stylesheets" aria-label="Permalink to &quot;Manage Scripts and Stylesheets&quot;">​</a></h1><p>Use this guide when you want to add a sitewide script or stylesheet — a snippet that runs on every rendered page of your community, or on a specific page — and register it with <code>gsds</code> so the change is tracked in <code>extensions_registry.json</code>.</p><p>Scripts and stylesheets are <strong>Extensions</strong> alongside Custom Widgets. Unlike widgets, they inject globally on the page rather than rendering inside the No-Code Builder.</p><h2 id="choose-a-subcommand" tabindex="-1">Choose a subcommand <a class="header-anchor" href="#choose-a-subcommand" aria-label="Permalink to &quot;Choose a subcommand&quot;">​</a></h2><p><code>gsds script</code> and <code>gsds style</code> share the same shape:</p><table tabindex="0"><thead><tr><th>You want to...</th><th>Use</th></tr></thead><tbody><tr><td>Create a local file in your repository</td><td><code>gsds script new</code> or <code>gsds style new</code></td></tr><tr><td>Register an external hosted URL</td><td><code>gsds script link</code> or <code>gsds style link</code></td></tr><tr><td>List everything currently registered</td><td><code>gsds script ls</code> or <code>gsds style ls</code></td></tr><tr><td>Remove an entry</td><td><code>gsds script rm</code> or <code>gsds style rm</code></td></tr></tbody></table><h2 id="add-a-local-script-or-stylesheet" tabindex="-1">Add a local script or stylesheet <a class="header-anchor" href="#add-a-local-script-or-stylesheet" aria-label="Permalink to &quot;Add a local script or stylesheet&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analytics-tracker</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brand-overrides</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>new</code> scaffolds the source file in your repository and adds an entry to the registry. Edit the file and re-run <code>gsds build</code> to update the registry.</p><h2 id="register-an-external-url" tabindex="-1">Register an external URL <a class="header-anchor" href="#register-an-external-url" aria-label="Permalink to &quot;Register an external URL&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cdn-analytics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cdn-analytics</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brand-theme</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>link</code> registers a hosted URL rather than a local file. The URL must end in <code>.js</code> for scripts and <code>.css</code> for stylesheets.</p><h2 id="common-flags-on-new-and-link" tabindex="-1">Common flags on <code>new</code> and <code>link</code> <a class="header-anchor" href="#common-flags-on-new-and-link" aria-label="Permalink to &quot;Common flags on `new` and `link`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--attr k=v</code></td><td>Add an HTML attribute to the injected tag (repeatable)</td></tr><tr><td><code>--page &lt;name&gt;</code></td><td>Scope the asset to a specific page instead of the whole site</td></tr><tr><td><code>--placement head|bodyStart|bodyEnd</code></td><td>Where to inject the script tag. Scripts only</td></tr><tr><td><code>--name &lt;slug&gt;</code></td><td>Explicit slug. Available on <code>link</code> only</td></tr></tbody></table><h2 id="scope-an-asset-to-one-page" tabindex="-1">Scope an asset to one page <a class="header-anchor" href="#scope-an-asset-to-one-page" aria-label="Permalink to &quot;Scope an asset to one page&quot;">​</a></h2><p>Sitewide is the default. Pass <code>--page</code> to inject on a specific page only:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> page-analytics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --page</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> product-tour</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --placement</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bodyEnd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="list-and-remove-entries" tabindex="-1">List and remove entries <a class="header-anchor" href="#list-and-remove-entries" aria-label="Permalink to &quot;List and remove entries&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Removing a named entry:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analytics-tracker</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brand-overrides</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>rm</code> refuses to delete a folder with contents. Pass <code>--force</code> to delete a non-empty folder.</p><h2 id="handle-registry-drift" tabindex="-1">Handle registry drift <a class="header-anchor" href="#handle-registry-drift" aria-label="Permalink to &quot;Handle registry drift&quot;">​</a></h2><p>If a registered script or stylesheet points at a file that no longer exists, <code>gsds build</code> refuses to regenerate the registry until you fix it. You have two ways out:</p><ul><li>Restore the missing file, or</li><li>Remove the stale entry with <code>gsds script rm &lt;name&gt;</code> or <code>gsds style rm &lt;name&gt;</code></li></ul><p><code>gsds create</code> warns on the same drift without failing so you can still scaffold new widgets while cleaning up.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Rebuild registries and validate for CI in the <a href="./reference/commands.html">Command reference</a></li><li>Understand what&#39;s stored where in <a href="./reference/project-files.html">Project files</a></li><li>Resolve the <code>Script &quot;x&quot; points at missing file</code> message in <a href="./reference/troubleshooting.html">Troubleshooting</a></li></ul>',29)])])}const k=s(n,[["render",d]]);export{g as __pageData,k as default};
